// Generated by scripts/build-coin-availability.mjs from content-source/coins/descriptions. Do not edit by hand.
// NexuAlpha's own coin descriptions (pt-BR).
export const COIN_DESCRIPTIONS = Object.freeze({"a7a5":"A7A5 é uma stablecoin atrelada ao rublo russo, lançada em 2025 por uma empresa registrada no Quirguistão e lastreada em depósitos em rublos em um banco russo. Funciona na Ethereum e na TRON e é usada em liquidações internacionais. O token e seu emissor foram alvo de sanções dos EUA, do Reino Unido e da UE, o que limita onde e como ele pode ser usado.","aave":"AAVE é o token de governança da Aave, um protocolo de empréstimos descentralizado em que os usuários depositam cripto para que outros peguem emprestado, ou tomam empréstimos usando a própria garantia. Os detentores votam em atualizações e parâmetros de risco e podem fazer staking de AAVE para ajudar a cobrir déficits do sistema. O projeto começou em 2017 como ETHLend, e o token original LEND foi convertido em AAVE em 2020.","aerodrome-finance":"AERO é o token da Aerodrome Finance, uma exchange descentralizada e central de liquidez na Base, a camada 2 da Ethereum lançada pela Coinbase. A Aerodrome entrou no ar em 2023 com base no modelo da Velodrome: os detentores bloqueiam AERO como veAERO para votar em quais pools de liquidez recebem as novas emissões de tokens. Quem vota recebe parte das taxas de negociação e dos incentivos dos pools que apoia.","agora-dollar":"AUSD é uma stablecoin em dólar emitida pela Agora e lançada em 2024. Cada token é lastreado por caixa, títulos de curto prazo do Tesouro dos EUA e operações compromissadas overnight, com reservas geridas pela VanEck e custodiadas pelo State Street. É usada em pagamentos, trading e DeFi, e é emitida em várias redes, como Ethereum, Sui, Mantle, Injective, Polygon e Monad.","akash-network":"AKT é o token nativo da Akash Network, um mercado descentralizado onde se oferece e aluga computação em nuvem, incluindo GPUs para treinar e rodar modelos de IA. A Akash é construída com o Cosmos SDK; o AKT é colocado em staking para proteger a rede, usado na governança e aceito como pagamento pela computação. Seu modelo de lances abertos faz os provedores competirem por preço em cada implantação.","akedo":"Akedo (AKE) é um token da BNB Smart Chain classificado no setor de inteligência artificial. O projeto se posiciona em torno de ferramentas de IA, e o AKE atua como token do ecossistema para participação e incentivos.","algorand":"Algorand (ALGO) é a moeda nativa da blockchain Algorand, fundada por Silvio Micali, professor do MIT e vencedor do Prêmio Turing, e lançada em 2019. Ela usa um modelo de prova de participação pura, em que os produtores de blocos são sorteados entre os detentores. O ALGO paga taxas e protege a rede, muito usada para ativos tokenizados e pagamentos.","ape-and-pepe":"Ape and Pepe (APEPE) é um token meme que junta dois personagens populares da internet: um macaco e o sapo Pepe. Ele funciona como token na rede Polygon PoS, onde as transferências são relativamente baratas. Como a maioria das memecoins, não tem uma função de protocolo própria, e o interesse por ele vem principalmente da comunidade e da atividade de negociação.","apenft":"NFT é o token da AINFT, antes chamada APENFT, projeto lançado em 2021 no ecossistema TRON. Começou com a ideia de levar obras de arte famosas para a blockchain como NFTs e operar um marketplace de NFTs, e o novo nome reflete um foco mais amplo que inclui serviços de IA. O token é usado na plataforma e existe na TRON, na Ethereum e na BNB Smart Chain.","aptos":"APT é o token nativo da Aptos, uma blockchain de camada 1 com prova de participação cuja mainnet foi lançada em 2022. O projeto foi criado por engenheiros que trabalharam na Diem, a blockchain da Meta, e usa a linguagem Move para contratos inteligentes. O APT paga as taxas de transação, é usado em staking por validadores e delegadores para proteger a rede e serve à governança.","apxusd":"apxUSD é uma stablecoin atrelada ao dólar emitida no Ethereum, na Base, na BNB Smart Chain e na Solana. Ela foi criada para manter um valor de cerca de um dólar e servir como unidade estável para transferências, negociação e aplicativos DeFi nessas redes.","arbitrum":"ARB é o token de governança do Arbitrum, um conjunto de redes de camada 2 do Ethereum desenvolvidas pela Offchain Labs com tecnologia optimistic rollup. Os detentores votam na Arbitrum DAO sobre atualizações e gastos da tesouraria, enquanto as taxas no Arbitrum One são pagas em ETH, e não em ARB. O token foi distribuído por airdrop em março de 2023.","arweave":"AR é o token nativo da Arweave, uma blockchain criada para armazenamento permanente de dados que entrou no ar em 2018. O usuário paga AR uma única vez para guardar arquivos; parte desse valor vai para um fundo que cobre o armazenamento no longo prazo, e os mineradores recebem AR por manter os dados disponíveis. A Arweave também hospeda o AO, uma camada de computação para programas autônomos e agentes de IA.","aster-2":"ASTER é o token da Aster, uma exchange descentralizada focada em contratos perpétuos e negociação à vista que opera principalmente na BNB Chain. O token é usado para governança, incentivos e benefícios ligados a taxas na plataforma. Foi lançado em 2025 e é mantido como token na BNB Smart Chain.","avalanche-2":"Avalanche (AVAX) é o token nativo da plataforma blockchain Avalanche, lançada em 2020 pela Ava Labs. O AVAX paga as taxas de transação, que são queimadas, e é colocado em staking por validadores na prova de participação. A Avalanche suporta contratos inteligentes compatíveis com Ethereum na C-Chain e permite que projetos lancem suas próprias blockchains personalizadas; a oferta máxima é de 720 milhões de tokens.","axie-infinity":"AXS é o token de governança e staking do Axie Infinity, um jogo em blockchain do estúdio vietnamita Sky Mavis em que os jogadores colecionam, cruzam e batalham com criaturas chamadas Axies. Os detentores podem fazer staking de AXS e votar sobre o tesouro da comunidade, e o token também é gasto em ações do jogo, como o cruzamento. O jogo roda principalmente na Ronin, uma rede ligada ao Ethereum criada pela Sky Mavis.","backpack":"BP é o token ligado à Backpack, uma corretora de criptomoedas e carteira de autocustódia que nasceu no ecossistema Solana e é mantida pela equipe por trás da coleção NFT Mad Lads. Ele é emitido como token SPL na Solana e busca conectar os usuários ao ecossistema e aos programas da comunidade da plataforma. Os usos específicos são definidos pela equipe da Backpack.","basic-attention-token":"BAT (Basic Attention Token) é um token ERC-20 ligado ao navegador Brave, que bloqueia por padrão a maioria dos rastreadores e anúncios. Quem opta por ver os anúncios do Brave, que respeitam a privacidade, pode receber BAT e repassá-lo para apoiar sites e criadores. O token foi lançado em 2017 e depois levado a outras redes, como Solana e Polygon.","beldex":"BDX é a moeda nativa da Beldex, uma blockchain focada em privacidade derivada do código do Monero e lançada em 2018. Ela oculta detalhes das transações com técnicas como assinaturas em anel e endereços ocultos, e sua rede de masternodes sustenta um mensageiro privado (BChat) e uma VPN descentralizada (BelNet). O BDX paga as taxas e é usado em staking pelos operadores de masternodes; também existe uma versão BEP-20 na BNB Smart Chain.","bfusd":"BFUSD é um ativo denominado em dólar criado pela Binance para uso dentro da própria plataforma, e não em uma blockchain pública. É usado principalmente como margem para negociar contratos futuros, e suas regras são definidas pela Binance, não por um protocolo on-chain. Diferente de uma stablecoin comum, não foi feito para circular livremente entre carteiras.","bianrensheng":"币安人生 (BinanceLife) é um token meme da BNB Smart Chain cujo nome em chinês significa algo como \"vida Binance\". Ele ganhou popularidade em 2025 nas comunidades cripto de língua chinesa como uma brincadeira com o ecossistema da Binance. Não tem função de protocolo, uso para taxas nem lastro; seu valor depende apenas do interesse da comunidade.","binancecoin":"BNB é a moeda nativa da BNB Chain e está ligada de perto ao ecossistema da Binance. Foi lançada em 2017 como token no Ethereum e depois migrou para sua própria rede, onde paga as taxas de gas, é colocada em staking por validadores e é usada na governança. A BNB tem um programa de queima periódica que retira moedas de circulação de forma permanente.","bitcoin":"Bitcoin (BTC) é a primeira criptomoeda, lançada em 2009 pelo criador pseudônimo Satoshi Nakamoto. Ele roda em sua própria blockchain de prova de trabalho, na qual mineradores protegem a rede e confirmam transações, e é usado para transferir valor e como reserva de valor de longo prazo. A oferta máxima é de 21 milhões de moedas, e a recompensa por bloco cai pela metade a cada quatro anos, aproximadamente.","bitcoin-cash":"Bitcoin Cash (BCH) é uma criptomoeda criada em agosto de 2017 por meio de um hard fork do Bitcoin. Seus defensores queriam blocos maiores para que a rede processasse mais transações com taxas baixas e funcionasse melhor para pagamentos do dia a dia. O BCH roda em sua própria blockchain de prova de trabalho, mantém o limite de 21 milhões de moedas e o calendário de halvings do Bitcoin e é usado principalmente para pagamentos entre pessoas.","bitcoin-cash-sv":"Bitcoin SV (BSV) é uma criptomoeda de prova de trabalho que se separou do Bitcoin Cash em novembro de 2018. Seus apoiadores, incluindo a nChain, queriam seguir o que consideram o design original do Bitcoin, com blocos muito grandes para alto volume de transações on-chain. O BSV usa mineração SHA-256, tem limite de 21 milhões de moedas e é usado em pagamentos e aplicações com muitos dados.","bitget-token":"Bitget Token (BGB) é o token utilitário do ecossistema da exchange Bitget. Ele dá descontos em taxas de negociação e acesso a eventos de lançamento de tokens, além de ser o token de gás da Morph, uma rede de camada 2 do Ethereum. No fim de 2024, a Bitget incorporou o Bitget Wallet Token (BWB) ao BGB e queimou grande parte do fornecimento.","bittensor":"TAO é a moeda nativa da Bittensor, uma rede descentralizada em que os participantes fornecem modelos de aprendizado de máquina e poder computacional e são recompensados conforme a utilidade do que entregam. A rede é dividida em sub-redes especializadas, e o TAO é usado para staking, registro em sub-redes e pagamento de serviços. Assim como o Bitcoin, tem oferta máxima de 21 milhões e halvings periódicos da nova emissão.","bittorrent":"BitTorrent (BTT) é o token ligado ao software de compartilhamento de arquivos BitTorrent, criado depois que a empresa de Justin Sun, fundador da TRON, comprou a BitTorrent Inc. em 2018. O BTT recompensa quem compartilha arquivos mais rápido, paga armazenamento descentralizado no BTFS e é o token de gás da BitTorrent Chain. Em 2021, passou por uma redenominação de 1 BTT antigo para 1.000 BTT novos.","bitway":"Bitway (BTW) é o token de um projeto de finanças descentralizadas (DeFi). Ele é emitido como token na BNB Smart Chain e no Ethereum, por isso pode ser guardado em carteiras comuns de ambas as redes.","blockchain-capital":"BCAP é um valor mobiliário digital emitido em 2017 pela gestora de venture capital Blockchain Capital, representando participação econômica em um de seus fundos. Foi um dos primeiros fundos de investimento tokenizados e foi criado como token na Ethereum. Por ser um valor mobiliário, e não um token utilitário, manter e transferir BCAP está sujeito a regras de mercado de capitais e a requisitos de elegibilidade de investidores.","blockstack":"STX é o token nativo da Stacks, uma camada de contratos inteligentes para o Bitcoin que antes se chamava Blockstack. A Stacks usa um mecanismo de consenso chamado Proof of Transfer, no qual mineradores comprometem BTC para participar da produção de blocos e a rede faz a liquidação no Bitcoin. O STX paga transações e contratos inteligentes em Clarity, e os detentores podem bloqueá-lo pelo processo de stacking para ajudar a proteger a rede.","bnb48-club-token":"KOGE é o token do 48 Club, também chamado de BNB48 Club, uma comunidade antiga de detentores de BNB. O grupo opera um validador e infraestrutura relacionada na BNB Smart Chain, e o KOGE é usado para associação e governança dentro da comunidade. É um token BEP-20 emitido na BNB Smart Chain.","bonk":"Bonk (BONK) é uma memecoin com tema de cachorro na Solana, lançada em dezembro de 2022, quando metade do suprimento foi distribuída por airdrop a usuários, desenvolvedores e comunidades de NFT da Solana. Não é stablecoin nem token de governança: funciona como token comunitário, para gorjetas e dentro de apps da Solana, como bots de negociação e jogos. Há também versões em ponte no Ethereum, na BNB Smart Chain e na Arbitrum.","canton-network":"Canton Coin (CC) é o token nativo da Canton Network, uma blockchain pensada para instituições financeiras reguladas, com tecnologia desenvolvida pela Digital Asset. A Canton permite que aplicativos diferentes mantenham seus dados privados e, ainda assim, liquidem transações entre si. O CC é usado para pagar as taxas da rede e para recompensar validadores e provedores de aplicativos que mantêm a rede funcionando.","cardano":"Cardano (ADA) é uma blockchain de prova de participação lançada em 2017 e desenvolvida com base em pesquisa por uma equipe liderada por Charles Hoskinson, cofundador do Ethereum. O ADA paga as taxas de transação, pode ser delegado a stake pools que protegem a rede pelo protocolo Ouroboros e é usado para votar na governança. O nome homenageia Ada Lovelace, e a oferta máxima é de 45 bilhões.","celestia":"Celestia é uma blockchain modular especializada em disponibilidade de dados: ela armazena e publica dados de transações para que rollups e outras redes não precisem manter uma camada de consenso completa própria. O TIA paga pela publicação de dados (\"blobs\"), é usado em staking para proteger a rede de prova de participação e na governança. A mainnet foi lançada em outubro de 2023 e é construída com o Cosmos SDK.","chain-2":"Onyxcoin (XCN) é o token da Onyx, um projeto que começou como Chain, responsável pelo lançamento do XCN em 2022, antes de mudar o nome para Onyx. O XCN é usado na governança do protocolo Onyx e no pagamento de taxas dentro do ecossistema, que inclui a própria rede Onyx. O token também existe no Ethereum, na Base e na BNB Smart Chain.","chainlink":"Chainlink (LINK) é o token de uma rede descentralizada de oráculos que leva dados externos, como preços de ativos, para contratos inteligentes. O LINK é usado para pagar os operadores de nós por seus serviços e pode ser colocado em staking para ajudar a proteger os serviços de oráculo. A Chainlink também opera o CCIP, um protocolo de mensagens entre blockchains, e seus feeds de preços são usados por muitos projetos de DeFi e de ativos tokenizados.","collector-crypt":"CARDS é o token da Collector Crypt, projeto na Solana que tokeniza cartas colecionáveis físicas graduadas, como cartas de Pokémon, guardadas em cofres profissionais. Cada carta é representada por um NFT que pode ser negociado on-chain ou resgatado pela carta física. O token CARDS está ligado ao ecossistema da plataforma, incluindo a abertura de pacotes digitais e incentivos à comunidade.","compound-governance-token":"COMP é o token de governança da Compound, um dos primeiros protocolos de empréstimo na Ethereum, onde usuários depositam cripto em pools compartilhados ou tomam empréstimos com garantia. Os detentores de COMP propõem e votam mudanças, como quais ativos são aceitos e como funcionam os modelos de juros. A oferta é limitada a 10 milhões, e a distribuição aos usuários começou em junho de 2020.","conflux-token":"Conflux (CFX) é a moeda nativa da Conflux Network, uma blockchain de camada 1 cuja rede principal foi lançada em 2020. Ela usa uma estrutura Tree-Graph que processa blocos em paralelo e combina mineração por prova de trabalho com uma camada de finalidade por prova de participação. O CFX paga taxas, é bloqueado como caução para o armazenamento de contratos e é usado em staking; a rede também oferece o eSpace, compatível com Ethereum.","convex-finance":"CVX é o token da Convex Finance, um protocolo do Ethereum lançado em 2021 e construído sobre a exchange Curve. A Convex permite que provedores de liquidez da Curve e detentores de CRV recebam recompensas turbinadas sem precisar bloquear CRV por conta própria. Os detentores de CVX podem bloqueá-lo como vlCVX para votar em como a Convex usa sua grande fatia do poder de voto da Curve e receber parte das taxas do protocolo.","cosmos":"ATOM é o token nativo do Cosmos Hub, a primeira blockchain lançada no ecossistema Cosmos, em 2019. Ele é usado em staking para proteger a rede de prova de participação, paga taxas de transação e dá aos detentores direito de voto na governança on-chain. O Hub se conecta a muitas redes independentes pelo protocolo IBC (Inter-Blockchain Communication), por isso o ATOM também aparece em redes como Osmosis e Kava.","crvusd":"crvUSD é uma stablecoin atrelada ao dólar americano, criada pela Curve Finance e lançada em 2023. Ela é cunhada com o depósito de cripto como ETH ou bitcoin embrulhado, ficando sobrecolateralizada. Seu diferencial é o LLAMMA, mecanismo que converte a garantia aos poucos quando os preços caem, em vez de liquidar tudo de uma vez. É usada em DeFi na Ethereum e em várias redes de camada 2.","crypto-com-chain":"Cronos (CRO), antes conhecido como Crypto.com Coin, é o token nativo das blockchains Cronos, lançadas pela equipe por trás da Crypto.com. O CRO paga o gas na rede Cronos EVM, pode ser colocado em staking para ajudar a proteger a rede e é usado em recompensas e vantagens no ecossistema da Crypto.com. Também existe como token ERC-20 no Ethereum.","curve-dao-token":"CRV é o token de governança da Curve Finance, uma exchange descentralizada lançada em 2020 e focada em trocas com baixo slippage entre ativos parecidos, como stablecoins. Quem trava CRV por até quatro anos recebe veCRV, que dá poder de voto, parte das taxas de negociação e influência sobre quais pools recebem emissões de CRV. O token está em várias redes, como Arbitrum e Polygon.","dai":"Dai (DAI) é uma stablecoin descentralizada criada para se manter próxima de um dólar americano. Novos DAI surgem quando usuários bloqueiam em contratos inteligentes uma garantia em cripto de valor maior que o DAI emitido; o sistema foi operado primeiro pela MakerDAO, que hoje se chama Sky. O DAI é muito usado em DeFi para negociação, empréstimos e pagamentos e funciona como token no Ethereum.","dash":"Dash (DASH) é uma criptomoeda lançada em 2014, primeiro com os nomes XCoin e Darkcoin, voltada para pagamentos rápidos e baratos. A rede combina mineração por prova de trabalho com masternodes, que viabilizam recursos como o InstantSend, para confirmações quase instantâneas, e a mistura baseada em CoinJoin, para mais privacidade. Parte de cada recompensa de bloco financia um tesouro, e os donos de masternodes votam em como ele é gasto.","decentraland":"MANA é o token do Decentraland, um mundo virtual em 3D em que os usuários possuem lotes de terreno como NFTs no Ethereum; a venda de tokens ocorreu em 2017 e a abertura ao público, em 2020. MANA é gasto em LAND, roupas de avatar, nomes e outros itens do marketplace, e os detentores votam regras e financiamentos pela DAO do Decentraland. É um token ERC-20 no Ethereum, também com ponte para a Polygon.","decred":"Decred (DCR) é uma criptomoeda lançada em 2016 que combina mineração por prova de trabalho com votação por prova de participação: os detentores bloqueiam DCR em tickets para aprovar blocos e votar mudanças de regras. Parte de cada recompensa de bloco vai para uma tesouraria cujos gastos são decididos por votação. O suprimento é limitado a 21 milhões de moedas, e a rede oferece privacidade opcional com o mixer integrado StakeShuffle.","derive":"Derive (DRV), antes conhecida como Lyra Finance, é uma exchange descentralizada de opções, futuros perpétuos e produtos estruturados on-chain. Ela roda em seu próprio rollup, a Derive Chain, construída com o OP Stack e com liquidação na Ethereum. O DRV é usado para governança e staking, e quem faz staking pode receber benefícios ligados à atividade da exchange.","dogecoin":"Dogecoin (DOGE) é uma criptomoeda criada em 2013 por Billy Markus e Jackson Palmer como uma brincadeira, com o cachorro Shiba Inu do meme 'doge' como símbolo. Ela roda em sua própria blockchain de prova de trabalho com o algoritmo Scrypt e costuma ser minerada em conjunto com o Litecoin. O DOGE é usado para gorjetas e pequenos pagamentos e não tem oferta máxima fixa.","dogwifcoin":"WIF (dogwifhat) é uma memecoin da Solana baseada na imagem de um cachorro Shiba Inu usando um gorro de tricô rosa. Foi lançada no fim de 2023 e se tornou um dos tokens meme mais reconhecidos da Solana. Não tem função de protocolo além de ser negociada e compartilhada pela comunidade, e também existe uma versão na Unichain.","doublezero":"2Z é o token da DoubleZero, um projeto de rede que dá aos validadores de blockchain acesso a links de fibra dedicados e de alta capacidade, em vez da internet pública comum. O primeiro foco é a Solana, onde o 2Z é emitido como token SPL. O token é usado para pagar o acesso à rede e para recompensar quem fornece largura de banda e infraestrutura.","eigenlayer":"EIGEN é o token da EigenCloud, antes chamada EigenLayer, um protocolo na Ethereum que permite fazer restaking do ETH já em staking para proteger outros serviços. Esses serviços, como camadas de disponibilidade de dados, oráculos e cargas de IA verificáveis, aproveitam a segurança econômica da Ethereum em vez de criar a própria. O EIGEN pode ser colocado em staking para garantir tarefas cujas falhas são difíceis de provar on-chain e também está disponível na Base.","ethena":"ENA é o token de governança da Ethena, protocolo que emite o USDe, um dólar sintético. Em vez de depósitos bancários, o USDe é lastreado por criptoativos combinados com posições vendidas em contratos futuros que os compensam, mantendo seu valor perto de um dólar. Quem tem ENA vota em decisões de risco e do protocolo e pode fazer staking; o token foi lançado no Ethereum em 2024.","ethena-usde":"Ethena USDe é um dólar sintético lançado pela Ethena em 2024 que busca se manter perto de um dólar americano. Em vez de ser lastreado por depósitos bancários, ele mantém garantias em cripto, como ETH e BTC, e compensa as variações de preço com posições vendidas em futuros, a chamada estratégia delta neutra. O USDe é usado em negociação e DeFi e está disponível em várias redes.","ether-fi":"ETHFI é o token de governança da ether.fi, um protocolo de staking líquido e restaking na Ethereum. Os usuários depositam ETH e recebem eETH ou weETH, tokens que representam ETH em staking que também é reapostado via EigenLayer para proteger outros serviços. O ETHFI, lançado em 2024, permite votar em decisões do protocolo, e o projeto também oferece um cartão de pagamento cripto.","ethereum":"Ether (ETH) é a moeda nativa do Ethereum, blockchain lançada em 2015 que executa contratos inteligentes e aplicativos descentralizados. O ETH paga as taxas de transação (gas) e é colocado em staking por validadores para proteger a rede, que trocou a mineração pela prova de participação em 2022. Muitos tokens, stablecoins e apps DeFi funcionam no Ethereum, e parte de cada taxa é queimada.","ethereum-classic":"Ethereum Classic (ETC) é a blockchain original do Ethereum, que continuou funcionando sem alterações após a divisão de 2016 causada pelo ataque à The DAO. Ela ainda usa mineração por prova de trabalho e suporta contratos inteligentes compatíveis com as ferramentas do Ethereum. O ETC paga taxas de transação e recompensa os mineradores, e seu fornecimento máximo é de cerca de 210,7 milhões de moedas.","ethereum-name-service":"ENS é o token de governança do Ethereum Name Service, o sistema que liga nomes legíveis como alice.eth a endereços de carteira e outros registros. Os detentores votam em propostas na ENS DAO, que administra o protocolo e seu tesouro. O token ERC-20 foi distribuído por airdrop a donos de nomes .eth e colaboradores em novembro de 2021 e tem oferta máxima de 100 milhões.","euro-coin":"EURC é uma stablecoin em euro emitida pela Circle, a empresa por trás do USDC, e é lastreada 1:1 em reservas denominadas em euro. Foi lançada em 2022 (originalmente como Euro Coin) e é emitida sob o regulamento MiCA da União Europeia como token de moeda eletrônica. É usada em pagamentos em euro, câmbio e DeFi na Ethereum, Solana, Base, Avalanche e outras redes.","falcon-finance":"Falcon USD (USDf) é um dólar sintético criado pelo protocolo Falcon Finance. Os usuários o emitem depositando garantias como stablecoins, BTC ou ETH, e o sistema mantém mais valor em garantias do que USDf em circulação. O USDf pode ser usado como ativo em dólar no DeFi ou colocado em staking no protocolo para receber sUSDf.","falcon-finance-ff":"FF é o token de governança e utilidade da Falcon Finance, um protocolo que emite o USDf, um dólar sintético cunhado com criptoativos, stablecoins e ativos reais tokenizados como garantia. Os detentores podem fazer staking de FF para obter benefícios no protocolo e votar em seus parâmetros. O token foi lançado em 2025 e está disponível na Ethereum e na BNB Smart Chain.","fetch-ai":"FET é o token da Artificial Superintelligence Alliance, formada em 2024 quando a Fetch.ai fundiu seu token com o AGIX da SingularityNET (e, inicialmente, com o OCEAN da Ocean Protocol). O FET paga serviços na rede de agentes de IA autônomos da Fetch.ai, é usado em staking para proteger a rede e serve à governança. Existe na Ethereum, Cardano, BNB Smart Chain e redes do ecossistema Cosmos.","filecoin":"Filecoin (FIL) é o token nativo de uma rede de armazenamento descentralizada criada pela Protocol Labs, com mainnet lançada em 2020. Os usuários pagam em FIL para guardar e recuperar dados, enquanto os provedores de armazenamento bloqueiam FIL como garantia e recebem FIL por manter os arquivos disponíveis. A rede usa provas criptográficas, como a prova de replicação e a prova de espaço-tempo, para verificar se os dados estão realmente armazenados.","first-digital-usd":"First Digital USD (FDUSD) é uma stablecoin em dólar emitida pela First Digital Labs, parte do grupo First Digital, sediado em Hong Kong, e lançada em 2023. Cada token deve ser lastreado um para um por dinheiro e equivalentes de caixa, como títulos de curto prazo do Tesouro americano, mantidos sob custódia. É usada como par de negociação, em pagamentos e para mover dólares entre redes como Ethereum, BNB Smart Chain, Solana, Sui e TON.","flare-networks":"FLR é o token nativo da Flare, uma blockchain de camada 1 compatível com EVM cujo token começou a ser distribuído em janeiro de 2023, em parte por meio de um airdrop para detentores de XRP. A Flare integra ferramentas de dados ao próprio protocolo, como o Flare Time Series Oracle (FTSO) para preços e o Flare Data Connector. O FLR é usado para taxas, staking, delegação a provedores de dados e governança.","floki":"FLOKI é um token meme movido pela comunidade, lançado em 2021 e batizado em homenagem ao cachorro Shiba Inu de Elon Musk. Além da origem meme, o projeto criou produtos como o jogo em blockchain Valhalla e as ferramentas DeFi da FlokiFi, e os detentores podem participar de votações de governança. O token existe na Ethereum e na BNB Smart Chain.","frax":"FRAX, agora identificado como Legacy Frax Dollar, é a stablecoin original da Frax Finance, lançada em dezembro de 2020 para acompanhar o dólar americano. Começou com um modelo parcialmente colateralizado e parcialmente algorítmico e depois passou a ter lastro total em colateral. A Frax lançou mais tarde o frxUSD como sua stablecoin principal, por isso este token anterior aparece como legado.","gatechain-token":"Gate (GT) é o token do ecossistema da exchange Gate, emitido pela primeira vez em 2019 como GateToken. É usado para descontos em taxas de negociação e eventos da plataforma, e como token de gás da blockchain própria da exchange. A Gate recompra e queima GT periodicamente, reduzindo o fornecimento total ao longo do tempo.","gho":"GHO é uma stablecoin descentralizada emitida pelo protocolo Aave e lançada em 2023, criada para acompanhar o dólar americano. Os usuários criam GHO tomando-o emprestado contra criptoativos depositados na Aave, de modo que cada unidade é lastreada por um colateral de valor maior. A taxa de empréstimo e outros parâmetros são definidos pela governança da Aave, e o GHO está disponível na Ethereum e em outras redes.","global-dollar":"Global Dollar (USDG) é uma stablecoin em dólar emitida pela Paxos e apoiada pela Global Dollar Network, um grupo de empresas de cripto e fintech. Cada USDG é lastreado por reservas em dinheiro e equivalentes de caixa e foi criado para ser resgatável um para um em dólares. É emitido sob o marco regulatório de stablecoins de Singapura e está disponível em redes como Ethereum, Solana e Arbitrum.","gnosis":"GNO é o token da Gnosis, projeto do ecossistema Ethereum fundado em 2015 que deu origem a ferramentas como a carteira multiassinatura Safe e a CoW Swap. Hoje o GNO serve principalmente para proteger a Gnosis Chain, rede compatível com EVM que se fundiu com a antiga xDai e cujos validadores fazem staking de GNO. Os detentores também votam com GNO na GnosisDAO, que administra a tesouraria e os rumos do projeto.","grass":"Grass é uma rede em que os usuários compartilham a banda de internet ociosa por meio de uma extensão de navegador ou aplicativo, e essa banda é usada para coletar dados públicos da web para treinar IA. GRASS é o token do projeto na Solana, usado para recompensar participantes, fazer staking nos roteadores da rede e votar. Ele foi distribuído pela primeira vez em um airdrop comunitário em 2024.","grx-chain":"GRX é a moeda nativa da GRX Chain, um projeto que roda em blockchain própria e é classificado entre os tokens ligados a exchanges. Moedas nativas desse tipo normalmente servem para pagar taxas de transação da rede e como utilidade dentro do ecossistema.","hash-2":"HASH é o token nativo da Provenance Blockchain, uma rede de prova de participação construída com o Cosmos SDK e voltada a serviços financeiros como empréstimos, valores mobiliários e registros de fundos. A fintech americana Figure Technologies liderou sua criação. O HASH paga as taxas da rede e é colocado em staking por validadores e delegadores, que protegem a rede e votam em propostas de governança.","hedera-hashgraph":"HBAR é a moeda nativa da Hedera, uma rede pública que chega a consenso usando hashgraph em vez de uma blockchain convencional. O HBAR paga transações, contratos inteligentes e armazenamento de arquivos e pode ser colocado em staking para ajudar a proteger a rede. A Hedera é supervisionada por um conselho de grandes empresas e instituições e é conhecida por taxas baixas definidas em dólar.","htx-dao":"HTX DAO (HTX) é o token do ecossistema da HTX, a exchange antes conhecida como Huobi. Lançado em 2024, serve para a governança da HTX DAO, onde os detentores votam em propostas, e para benefícios na plataforma. Quem tinha o antigo Huobi Token (HT) pôde convertê-lo em HTX, que circula na TRON, no Ethereum e na BNB Smart Chain.","hyperliquid":"HYPE é o token nativo da Hyperliquid, uma blockchain de camada 1 construída em torno de um livro de ofertas on-chain para contratos perpétuos e negociação à vista. O HYPE paga o gas da rede, é colocado em staking com os validadores que rodam o consenso HyperBFT e tem papel na governança. O token foi lançado no fim de 2024, e uma grande parte foi distribuída aos primeiros usuários por meio de um airdrop.","injective-protocol":"INJ é o token nativo da Injective, uma blockchain de camada 1 construída com o Cosmos SDK para aplicações financeiras, como negociação com livro de ofertas, derivativos e ativos do mundo real tokenizados. O INJ é usado em staking para proteger a rede de prova de participação, além de pagar taxas e servir à governança. Parte das taxas do protocolo vai para leilões periódicos de queima, que retiram INJ de circulação de forma permanente.","instadapp":"FLUID é o token de governança da Fluid, o protocolo DeFi antes chamado Instadapp; o antigo token INST foi renomeado para FLUID em 2024. A Fluid combina empréstimos e uma exchange descentralizada sobre uma camada de liquidez compartilhada, de modo que os mesmos depósitos servem como colateral e como liquidez para negociação. Os detentores votam nos parâmetros do protocolo, que roda no Ethereum e em outras redes.","internet-computer":"ICP é o token nativo da Internet Computer, blockchain desenvolvida pela DFINITY Foundation, lançada em 2021 e capaz de hospedar aplicativos web completos e seus dados diretamente na rede. O ICP é convertido em ciclos (cycles) que pagam processamento e armazenamento e pode ser bloqueado em neurônios para votar na governança da rede. Também existem versões em ponte no Ethereum e na Base.","iota":"IOTA é a moeda nativa da rede IOTA, projeto iniciado em 2016 e apoiado pela IOTA Foundation, sediada em Berlim. No início usava uma estrutura sem blocos chamada Tangle, voltada para IoT e dados, e em 2025 migrou para um novo modelo, o IOTA Rebased, com prova de participação delegada e contratos inteligentes em Move. IOTA é usada para pagar taxas de rede e para staking.","janus-henderson-anemoy-aaa-clo-fund":"JAAA é a versão tokenizada de cotas de um fundo que investe em obrigações de empréstimos colateralizados (CLOs) com rating AAA, um tipo de título formado por pacotes de empréstimos a empresas. A gestão é da Janus Henderson, e a emissão on-chain é feita pela Anemoy, ligada à rede de ativos reais Centrifuge. O token existe em Ethereum, Base, Solana e outras redes, e o acesso costuma ser restrito a investidores elegíveis.","jasmycoin":"JASMY é o token da Jasmy, empresa japonesa fundada por ex-executivos da Sony e focada em dispositivos de Internet das Coisas (IoT) e dados pessoais. A proposta é permitir que as pessoas controlem os dados gerados por seus aparelhos e decidam como compartilhá-los. JASMY é um token ERC-20 na Ethereum usado dentro dessa plataforma de dados.","jito-governance-token":"JTO é o token de governança da Jito, projeto da Solana conhecido pelo JitoSOL, um token de staking líquido, e pelo cliente validador Jito, que lida com o MEV, o valor extra gerado pela ordem das transações. Os detentores de JTO votam na Jito DAO sobre taxas, uso da tesouraria e mudanças no protocolo. O token foi distribuído por airdrop em dezembro de 2023.","jupiter-exchange-solana":"Jupiter (JUP) é o token da Jupiter, um agregador de exchanges descentralizadas na Solana que divide cada troca entre várias fontes de liquidez para encontrar rotas eficientes. O JUP é usado na governança da Jupiter DAO, onde os detentores votam em propostas e novos lançamentos. Ele foi distribuído em um grande airdrop para a comunidade em janeiro de 2024.","just":"JUST (JST) é o token de governança da JUST, uma plataforma de finanças descentralizadas construída na TRON e lançada em 2020. Os detentores votam em propostas sobre seus produtos, como o mercado de empréstimos JustLend, e o JST é usado para pagar certas taxas do protocolo. Parte da receita da plataforma é usada para recomprar e queimar JST.","kaia":"Kaia (KAIA) é uma blockchain de camada 1 formada em 2024 pela fusão da Klaytn, lançada pela Kakao, com a Finschia, lançada pela LINE, duas redes ligadas a grandes apps de mensagens da Ásia. O KAIA substituiu os antigos tokens KLAY e FNSA e é usado para taxas, staking e governança. A rede é compatível com EVM e mira carteiras e miniapps acessados por mensageiros como Kakao e LINE.","kamino":"KMNO é o token de governança da Kamino Finance, uma plataforma DeFi na Solana que reúne empréstimos, cofres de liquidez automatizados e posições alavancadas em uma única interface. Os detentores usam KMNO para votar em decisões do protocolo e podem fazer staking dentro da Kamino. O token foi distribuído aos primeiros usuários por meio de um airdrop em 2024.","kaspa":"Kaspa (KAS) é uma criptomoeda de prova de trabalho construída sobre um blockDAG, estrutura que permite criar vários blocos em paralelo em vez de uma única cadeia. Esse design, baseado no protocolo GHOSTDAG, permite blocos muito frequentes e confirmações rápidas. O KAS é usado em pagamentos e taxas, e a rede teve um lançamento justo em novembro de 2021, sem pré-mineração.","kinesis-gold":"Kinesis Gold (KAU) é uma moeda digital lastreada em ouro em que cada token representa um grama de ouro físico alocado e guardado em cofres. Faz parte do sistema monetário Kinesis, que divide parte das taxas de transação com detentores e usuários como rendimento. O KAU pode ser guardado, enviado ou gasto, e o ouro por trás dele pode ser resgatado conforme as regras da plataforma.","kinesis-silver":"KAG é um token emitido pela Kinesis em que cada unidade representa uma onça troy de prata física guardada em cofres de forma alocada. Ele permite manter, enviar e gastar prata no formato digital, e o metal pode ser resgatado conforme as regras do emissor. No sistema Kinesis, é usado para pagamentos e para reserva de valor, e há uma versão na Ethereum.","kite-2":"KITE é o token nativo da Kite, uma blockchain focada em pagamentos e identidade para agentes de IA, para que softwares autônomos tenham identidade verificável e paguem por serviços sozinhos. A Kite é uma rede compatível com EVM construída com tecnologia da Avalanche, e o KITE é usado em staking, segurança da rede, governança e incentivos. O token também existe no Ethereum, na BNB Smart Chain e na Hyperliquid.","kucoin-shares":"KuCoin Token (KCS) é o token nativo da exchange KuCoin, lançado em 2017. Ele oferece descontos em taxas de negociação e outros benefícios na plataforma, e é o token de gás da KCC, a KuCoin Community Chain. A KuCoin recompra e queima KCS regularmente, com a meta de longo prazo de reduzir o fornecimento para 100 milhões de tokens.","layerzero":"ZRO é o token da LayerZero, um protocolo de interoperabilidade que permite que aplicações enviem mensagens e tokens entre blockchains diferentes. Em vez de ser uma rede própria, a LayerZero mantém contratos de endpoint em várias redes, como Ethereum, Arbitrum, Base e BNB Smart Chain. O ZRO foi lançado em 2024 e é usado na governança do protocolo.","leo-token":"LEO Token (LEO) é o token utilitário da iFinex, empresa por trás da corretora Bitfinex, lançado em 2019. Os detentores podem usar o LEO para pagar taxas de negociação menores e ter outras vantagens na Bitfinex e em plataformas relacionadas. A iFinex se comprometeu a recomprar e queimar LEO ao longo do tempo, o que reduz aos poucos a oferta em circulação. O token existe no Ethereum e em outras redes.","lido-dao":"LDO é o token de governança da Lido, um serviço de staking líquido em que o usuário deposita ETH e recebe stETH, um token que continua utilizável em DeFi enquanto acumula recompensas de staking. Quem tem LDO vota na Lido DAO sobre parâmetros do protocolo, escolha de operadores de nós e uso da tesouraria. O token foi lançado no Ethereum no fim de 2020 e também circula em várias redes de camada 2.","lighter":"LIT é o token nativo da Lighter, uma exchange descentralizada focada em contratos futuros perpétuos. A Lighter funciona como um rollup de conhecimento zero na Ethereum, usando provas criptográficas para mostrar que as ordens foram casadas e liquidadas corretamente. O LIT é emitido na Ethereum e também existe na Robinhood Chain.","litecoin":"Litecoin (LTC) é uma das primeiras criptomoedas, lançada em 2011 por Charlie Lee como uma variante mais leve e rápida do Bitcoin. Ela roda em sua própria blockchain de prova de trabalho com o algoritmo Scrypt e gera um bloco a cada 2,5 minutos, aproximadamente. O LTC é usado principalmente para pagamentos e transferências, e sua oferta máxima é de 84 milhões de moedas, quatro vezes a do Bitcoin.","mantle":"Mantle (MNT) é o token nativo da Mantle Network, uma rede de camada 2 do Ethereum que agrupa transações e as liquida no Ethereum. O MNT paga as taxas de gás na Mantle e é usado para votar em propostas de governança. O projeto surgiu da BitDAO, cujo token BIT foi convertido em MNT em 2023.","memecore":"MemeCore (M) é um projeto construído em torno da cultura meme que se apresenta como uma blockchain dedicada a memecoins e suas comunidades. O token M pertence à categoria meme e está disponível como token na BNB Smart Chain.","meteora":"MET é o token da Meteora, protocolo de liquidez na Solana cujos pools são usados por traders, lançamentos de novos tokens e outros apps DeFi. Ela é conhecida pelos pools dinâmicos, como o modelo DLMM, que distribui a liquidez em faixas de preço e ajusta as taxas conforme a volatilidade. O MET foi lançado em 2025 e serve para a governança do protocolo.","midnight-3":"NIGHT é o token nativo da Midnight, uma blockchain focada em privacidade desenvolvida pela equipe por trás da Cardano e operada como rede parceira da Cardano. Ela usa provas de conhecimento zero para que aplicações mantenham dados sensíveis em sigilo e, ainda assim, provem que as regras foram cumpridas. Manter NIGHT gera DUST, um recurso protegido usado para pagar as transações, enquanto o próprio NIGHT serve para governança e produção de blocos.","monad":"Monad (MON) é a moeda nativa da Monad, uma blockchain de camada 1 compatível com Ethereum cuja rede principal foi lançada em novembro de 2025. Ela busca alto desempenho executando transações em paralelo e usando o consenso próprio MonadBFT, sem deixar de rodar contratos inteligentes padrão do Ethereum. O MON paga o gas e é colocado em staking por validadores e delegadores para proteger a rede.","monero":"Monero (XMR) é uma criptomoeda focada em privacidade, lançada em 2014, que mantém os detalhes das transações privados por padrão. Ela usa assinaturas em anel, endereços ocultos e transações confidenciais para esconder remetentes, destinatários e valores. O Monero é minerado com o algoritmo de prova de trabalho RandomX, pensado para CPUs comuns, e mantém uma pequena recompensa permanente por bloco (emissão de cauda).","morpho":"MORPHO é o token de governança da Morpho, um protocolo de empréstimos descentralizado no Ethereum e em outras redes EVM, como a Base. A Morpho permite que qualquer pessoa crie mercados de empréstimo isolados, enquanto cofres administrados por curadores externos distribuem os depósitos entre eles. Os detentores de MORPHO votam na Morpho DAO sobre atualizações e a tesouraria do protocolo.","mx-token":"MX é o token da plataforma MEXC, uma exchange centralizada de criptomoedas fundada em 2018. Manter ou usar MX pode dar direito a descontos nas taxas de negociação, acesso a eventos de lançamento de novos tokens e participação nas votações de listagem da MEXC. É emitido como token ERC-20 no Ethereum e também existe na Morph L2.","near":"NEAR Protocol (NEAR) é uma blockchain de camada 1 com prova de participação, no ar desde 2020, que usa um modelo de fragmentação (sharding) chamado Nightshade para distribuir o trabalho pela rede. O NEAR paga taxas de transação e de armazenamento e é colocado em staking com validadores. O projeto tem se voltado cada vez mais para IA e agentes controlados pelos usuários, e o cofundador Illia Polosukhin é coautor do conhecido artigo 'Attention Is All You Need'.","neo":"NEO é a moeda nativa da Neo, uma blockchain de contratos inteligentes fundada na China em 2014 como Antshares e renomeada em 2017. A Neo chega ao consenso por tolerância bizantina delegada (dBFT). NEO é usado na governança, incluindo a eleição do conselho que conduz o consenso, e mantê-lo gera GAS, o token separado que paga as taxas da rede. O fornecimento é fixo em 100 milhões e o NEO não pode ser fracionado.","nexo":"NEXO é o token da Nexo, plataforma de empréstimos cripto e ativos digitais fundada em 2018. A quantidade de NEXO que o usuário mantém na plataforma define seu nível de fidelidade, que influencia as taxas de empréstimo e outros benefícios da conta. Ele começou como token ERC-20 na Ethereum e também está disponível em outras redes, como a Polygon.","non-playable-coin":"Non-Playable Coin (NPC) é um token meme inspirado na piada da internet sobre pessoas que agem como personagens de fundo de um videogame. Foi lançado no Ethereum em 2023 e projetado para que os tokens e uma coleção de NFTs vinculada possam ser convertidos entre si. Desde então, ganhou pontes para Solana, BNB Smart Chain, Base e outras redes.","official-trump":"Official Trump (TRUMP) é um token meme na Solana ligado a Donald Trump, lançado em janeiro de 2025, pouco antes de sua posse. Ele não tem utilidade de protocolo, como pagamento de taxas ou staking; funciona como token colecionável e de comunidade. Grande parte da oferta foi destinada a entidades afiliadas e é liberada segundo um cronograma de vários anos.","okb":"OKB é o token utilitário do ecossistema OKX. Ele oferece descontos em taxas de negociação e benefícios na plataforma e é o token de gas da X Layer, a rede de camada 2 da própria OKX. Em 2025, uma grande queima fixou a oferta total de OKB em 21 milhões, o que significa que nenhum novo OKB pode ser criado.","olympus":"OHM é o token da Olympus, um protocolo DeFi lançado no Ethereum em 2021 que mantém uma tesouraria de ativos para dar suporte ao token. A Olympus gerencia a oferta de OHM com recompras e um sistema de faixas, e os detentores podem tomar stablecoins emprestadas usando OHM em staking como colateral pelo recurso Cooler Loans. O OHM também é o token de governança da OlympusDAO.","ondo-finance":"ONDO é o token de governança da Ondo Finance, projeto que leva ativos financeiros tradicionais, como fundos de títulos do Tesouro americano, para as blockchains na forma de tokens. Quem tem ONDO participa das decisões sobre o ecossistema Ondo e seus produtos. O token funciona no Ethereum, e os produtos tokenizados da Ondo são voltados tanto para instituições quanto para usuários on-chain.","open-usd":"Open USD (OUSD) é uma stablecoin criada para manter o valor de um dólar americano. Ela é emitida como token em várias redes, incluindo Ethereum, Solana, Base e Tempo, e pode ser usada em pagamentos, transferências e como saldo em dólar em aplicações on-chain.","optimism":"OP é o token de governança do Optimism Collective, que supervisiona a OP Mainnet, uma rede de camada 2 do Ethereum que usa optimistic rollups para agrupar transações e liquidá-las no Ethereum. Os detentores votam na Token House sobre atualizações, incentivos e subsídios, enquanto as taxas na OP Mainnet são pagas em ETH, não em OP. O token foi lançado em 2022, e o mesmo software OP Stack sustenta um grupo de redes chamado Superchain.","origintrail":"TRAC é o token da OriginTrail, que opera um Grafo de Conhecimento Descentralizado (DKG) para publicar e conectar dados verificáveis, com uso em cadeias de suprimento e aplicações de IA. O TRAC é gasto para publicar ativos de conhecimento na rede e é colocado em staking pelos operadores de nós que armazenam e servem esses dados. É um token ERC-20 no Ethereum, com versão na Base.","pancakeswap-token":"CAKE é o token da PancakeSwap, exchange descentralizada lançada na BNB Smart Chain em 2020 e depois expandida para Ethereum, Arbitrum, Base, Aptos e outras redes. Os usuários trocam tokens usando pools de liquidez automatizados, e o CAKE é usado em incentivos de liquidez, staking e votações de governança. Parte das taxas da plataforma é usada para recomprar e queimar CAKE, reduzindo a oferta.","pax-gold":"PAX Gold (PAXG) é um token lastreado em ouro lançado em 2019 pela Paxos, uma empresa fiduciária regulada nos Estados Unidos. Cada token representa a propriedade de uma onça troy de ouro fino em barras London Good Delivery guardadas em cofres profissionais. Por ser um token ERC-20 no Ethereum, permite guardar e transferir ouro em pequenas frações.","paypal-usd":"PayPal USD (PYUSD) é uma stablecoin em dólar emitida pela Paxos para o PayPal e lançada em 2023. Cada token é lastreado por depósitos em dólar, títulos do Tesouro americano de curto prazo e equivalentes de caixa semelhantes, e foi pensado para ser resgatável um para um. O PYUSD pode ser enviado e gasto no PayPal e no Venmo e também circula em blockchains como Ethereum, Solana e Arbitrum.","pearl-2":"Pearl (PRL) é a moeda nativa de sua própria blockchain e aparece na categoria de inteligência artificial. Como a maioria das moedas de camada 1, o PRL é usado para pagar taxas da rede e sustentar o funcionamento da cadeia.","pendle":"Pendle é um protocolo DeFi lançado em 2021 que divide ativos que geram rendimento em duas partes: um token de principal (PT) e um token de rendimento (YT), negociados separadamente. Assim, os usuários podem travar um rendimento fixo ou se posicionar sobre o rendimento futuro. O token PENDLE é usado na governança e pode ser travado ou colocado em staking para receber parte da receita do protocolo e direcionar incentivos.","pepe":"Pepe (PEPE) é uma memecoin lançada no Ethereum em abril de 2023, inspirada no meme Pepe the Frog. Não tem roteiro formal nem utilidade embutida além de ser um token comunitário negociado e compartilhado. Seu fornecimento fixo de cerca de 420,69 trilhões de tokens foi liberado no lançamento, e há versões em ponte em outras redes.","pi-network":"Pi (PI) é a moeda nativa da Pi Network, projeto iniciado em 2019 que permitia acumular moedas por um aplicativo de celular, sem a mineração de alto consumo de energia. A mainnet aberta entrou no ar em fevereiro de 2025, depois de anos em que os saldos só podiam ser usados dentro do ecossistema do app. O consenso da rede é baseado no Stellar Consensus Protocol, e normalmente os usuários precisam verificar a identidade antes de migrar as moedas para a mainnet.","pieverse":"PIEVERSE é o token da Pieverse, um projeto do setor de inteligência artificial que desenvolve infraestrutura para agentes de IA, incluindo pagamentos on-chain. Ele é emitido na BNB Smart Chain e no Ethereum e é usado para participar do ecossistema Pieverse.","plasma":"Plasma é uma blockchain de camada 1 criada especificamente para pagamentos com stablecoins, principalmente USDT, com recursos como transferências de USDT sem taxa. É compatível com EVM e ancora seu estado no Bitcoin para reforçar a segurança; a mainnet beta foi lançada em setembro de 2025. XPL é o token nativo, que paga as taxas de outras operações e é usado em staking pelos validadores para proteger a rede.","polkadot":"DOT é a moeda nativa da Polkadot, rede fundada pelo cofundador do Ethereum Gavin Wood que conecta várias blockchains especializadas a uma camada de segurança compartilhada. O DOT é usado na governança on-chain, no staking sob um sistema de prova de participação nomeada e para obter espaço de bloco para as redes conectadas. A mainnet da Polkadot foi lançada em 2020.","polygon-ecosystem-token":"POL é o token nativo da rede Polygon e a atualização do MATIC, que os detentores começaram a migrar na proporção 1:1 em setembro de 2024. O POL paga o gás na Polygon PoS e é colocado em staking pelos validadores que protegem a rede. Ele também foi pensado para atender outras redes conectadas pela AggLayer da Polygon.","pudgy-penguins":"PENGU é o token da Pudgy Penguins, uma marca de pinguins em desenho que começou como coleção de NFTs na Ethereum em 2021 e depois chegou a brinquedos e mídia. Lançado na Solana em dezembro de 2024, o PENGU foi distribuído em um amplo airdrop para detentores dos NFTs e outras comunidades cripto. Funciona principalmente como token de comunidade e meme, e hoje está em várias redes.","pump-fun":"PUMP é o token da Pump.fun, uma plataforma na Solana que permite a qualquer pessoa criar e lançar uma memecoin em poucos passos, com a negociação inicial feita em uma curva de vinculação (bonding curve). O token PUMP foi lançado em 2025 e está ligado ao ecossistema e à comunidade da plataforma. É um token da Solana, então fica em carteiras compatíveis com Solana.","pyth-network":"PYTH é o token da Pyth Network, um oráculo que fornece preços de mercado para aplicações blockchain. Os dados vêm diretamente de publicadores primários, como exchanges e empresas de trading, e a rede começou na Solana antes de se expandir para muitas outras blockchains. O PYTH é usado na governança e em um staking que responsabiliza os publicadores pela qualidade dos preços.","quant-network":"QNT é o token da Quant, empresa cuja tecnologia Overledger busca conectar diferentes blockchains entre si e com sistemas corporativos já existentes. Empresas e desenvolvedores usam QNT para pagar licenças e o acesso à rede da Quant. O token funciona no Ethereum e tem oferta limitada de cerca de 14,6 milhões de QNT.","railgun":"RAIL é o token de governança da Railgun, um protocolo de privacidade para o Ethereum e outras redes EVM. A Railgun usa provas de conhecimento zero para que os usuários guardem, enviem e troquem tokens em um saldo protegido, sem expor publicamente o histórico do endereço. Quem faz staking de RAIL vota em mudanças do protocolo e recebe parte das taxas cobradas quando ativos entram e saem do sistema privado.","rain":"Rain (RAIN) é um token do setor de finanças descentralizadas (DeFi), emitido na Arbitrum One, uma rede de camada 2 do Ethereum. Por ser um token da Arbitrum, ele é transferido e usado em carteiras e aplicativos compatíveis com Ethereum, e as taxas da rede são pagas em ETH, não em RAIN.","raydium":"RAY é o token da Raydium, um formador de mercado automatizado (AMM) e provedor de liquidez na Solana lançado em 2021. Os usuários trocam tokens e adicionam liquidez a pools, e muitos tokens novos da Solana ganham seus primeiros pools de negociação na Raydium. O RAY é usado em staking e incentivos de liquidez, e parte das taxas de negociação é usada para recomprar RAY.","re-protocol-reusd":"reUSD é um token denominado em dólar do Re Protocol, projeto que conecta capital on-chain ao mercado de resseguros, no qual seguradoras repassam parte de seus riscos a outras empresas. Ele foi projetado para manter um valor estável em dólar e é sustentado por ativos ligados a resseguros. O token está disponível em várias redes, incluindo Ethereum, Solana, Arbitrum, Base e Avalanche.","render-token":"Render (RENDER) é o token da Render Network, que conecta quem precisa de poder de GPU para renderização 3D e tarefas de IA a operadores de nós com GPUs ociosas. Os criadores pagam os trabalhos em RENDER, e os operadores o recebem pelo trabalho concluído. O projeto foi iniciado por Jules Urbach, fundador da OTOY, e em 2023 migrou do Ethereum para a Solana, substituindo o antigo token RNDR.","ripple":"XRP é o ativo nativo do XRP Ledger, blockchain pública lançada em 2012 e associada de perto à empresa Ripple. Foi pensado para pagamentos rápidos e baratos e para liquidação internacional: as transações são confirmadas em poucos segundos por um processo de consenso, sem mineração. Todos os 100 bilhões de XRP foram criados no lançamento, e uma pequena taxa é destruída a cada transação.","ripple-usd":"Ripple USD (RLUSD) é uma stablecoin em dólar emitida pela Ripple e lançada em dezembro de 2024. É lastreada por depósitos em dólar, títulos do Tesouro americano de curto prazo e equivalentes de caixa e foi criada para ser resgatável um para um. O RLUSD é emitido nativamente no XRP Ledger e no Ethereum e é voltado principalmente para pagamentos e uso institucional.","safo":"SAFO é uma cota tokenizada de um fundo no estilo money market oferecido pela Spiko, fintech de Paris, com o fundo subjacente gerido pela gestora Amundi. O fundo acompanha as taxas de juros overnight por meio de contratos de swap, e o token permite que investidores elegíveis mantenham e transfiram cotas em blockchains públicas. É emitido em várias redes, como Ethereum, Arbitrum, Base, Polygon, Starknet e Stellar.","sei-network":"Sei é uma blockchain de camada 1 feita para aplicações de negociação rápidas, com finalidade em menos de um segundo e processamento paralelo de transações. Desde a atualização v2, roda uma EVM paralelizada, permitindo contratos inteligentes no estilo da Ethereum. O SEI paga o gás, é usado em staking para proteger a rede de prova de participação e na governança; a mainnet foi lançada em agosto de 2023.","shiba-inu":"Shiba Inu (SHIB) é um token meme lançado em 2020 por um criador anônimo conhecido como Ryoshi, batizado com o nome da raça de cachorro popularizada pela Dogecoin. Começou como token ERC-20 no Ethereum e cresceu até formar um ecossistema comunitário com uma exchange descentralizada, a ShibaSwap, e uma rede de camada 2, a Shibarium. Sua oferta chega a centenas de trilhões, e parte dela já foi queimada.","shuffle-2":"SHFL é o token da Shuffle, uma plataforma de jogos online que aceita criptomoedas. É um token ERC-20 na Ethereum usado dentro da plataforma em recursos como programas de recompensas e um sorteio para detentores. Seu papel está ligado à própria plataforma Shuffle, e não a uma blockchain ou protocolo independente.","sky":"Sky (SKY) é o token de governança do protocolo Sky, novo nome adotado pela MakerDAO em 2024. Os detentores votam em parâmetros de risco e garantias do protocolo, que emite a stablecoin USDS ao lado da antiga DAI. O SKY é a versão atualizada do MKR: cada MKR pode ser convertido em 24.000 SKY.","societe-generale-forge-eurcv":"EUR CoinVertible (EURCV) é uma stablecoin em euro emitida pela Societe Generale-FORGE, subsidiária de ativos digitais do banco francês Société Générale. Cada token foi criado para valer um euro e é lastreado por reservas em euro mantidas pelo emissor. Lançada primeiro no Ethereum em 2023, hoje também está disponível na Solana, na Stellar e no XRP Ledger, sendo usada em pagamentos e liquidações.","sofiusd":"SoFiUSD é uma stablecoin em dólar emitida pela SoFi, empresa americana de finanças pessoais que possui licença de banco nacional nos EUA. Ela foi criada para ser resgatável na proporção de um para um em dólares, com reservas mantidas pelo emissor, sendo uma das poucas stablecoins emitidas diretamente por um banco regulado nos EUA. Funciona no Ethereum e na Solana e é voltada a pagamentos e liquidação.","solana":"Solana (SOL) é a moeda nativa da blockchain Solana, que entrou no ar em 2020 com foco em alta capacidade e taxas baixas. O SOL paga as taxas de transação e é delegado em staking a validadores que protegem a rede por prova de participação. Uma técnica de marcação de tempo chamada Proof of History ajuda a ordenar as transações, e a Solana abriga muitos apps de DeFi, NFT e pagamentos.","sonic-3":"S é a moeda nativa da Sonic, rede antes conhecida como Fantom, que foi relançada com novo nome e uma blockchain atualizada no fim de 2024. Detentores de FTM puderam converter para S na proporção de 1:1. O S paga taxas de transação, é colocado em staking para proteger a rede e é usado na governança; a Sonic é compatível com EVM e repassa aos desenvolvedores parte das taxas geradas por seus apps.","spiko-amundi-overnight-swap-fund-eur":"EURSAFO é uma cota tokenizada de um fundo em euros lançado pela Spiko, fintech de Paris, em parceria com a gestora Amundi. Cada token representa uma cota do fundo cujo valor busca acompanhar as taxas de juros overnight do euro, registrada diretamente em blockchains públicas. É emitido em várias redes, como Ethereum, Arbitrum, Base, Polygon, Starknet e Stellar.","stable-2":"STABLE é o token nativo da Stable, uma blockchain de camada 1 criada especificamente para pagamentos com stablecoins, com foco em USDT. Na Stable, as taxas de transação são pagas em USDT, e não em uma moeda de gas separada, para que qualquer pessoa possa enviar dólares sem precisar de outro token. O STABLE tem outro papel: sustentar a segurança e a governança da rede.","starknet":"STRK é o token nativo da Starknet, uma rede de camada 2 da Ethereum desenvolvida pela StarkWare. A Starknet é um rollup de validade: agrupa muitas transações e prova sua correção à Ethereum com provas criptográficas STARK, e seus contratos inteligentes são escritos na linguagem Cairo. O STRK, lançado em 2024, paga taxas de transação e é usado em staking e governança.","stellar":"Stellar (XLM), também chamado de lumen, é o ativo nativo da rede Stellar, lançada em 2014 por Jed McCaleb e pela fundação sem fins lucrativos Stellar Development Foundation. A rede foca em pagamentos e na emissão de ativos tokenizados, como stablecoins, e usa o Stellar Consensus Protocol em vez de mineração. O XLM paga pequenas taxas de transação e cada conta precisa manter um saldo mínimo.","sui":"SUI é a moeda nativa da Sui, uma blockchain de camada 1 desenvolvida pela Mysten Labs, empresa fundada por ex-engenheiros do projeto Diem, da Meta. O SUI paga taxas de transação, pode ser colocado em staking com validadores para proteger a rede e é usado na governança. A mainnet foi lançada em 2023, usa a linguagem Move e tem oferta máxima de 10 bilhões de SUI.","sun-token":"SUN é o token de governança da SUN.io, uma plataforma DeFi na blockchain TRON que oferece trocas de stablecoins, pools de liquidez e a exchange descentralizada SunSwap. Os detentores podem bloquear SUN para votar em propostas e aumentar sua participação nos programas de mineração de liquidez. O projeto surgiu em 2020 no ecossistema de Justin Sun, fundador da TRON.","swissborg":"BORG é o token da SwissBorg, um aplicativo de investimento em cripto sediado na Suíça e fundado em 2017. O BORG substituiu o antigo token CHSB em uma migração em 2024 e é usado dentro do app para liberar níveis de assinatura mais altos e outros benefícios. É emitido no Ethereum e na Solana.","syrup":"SYRUP é o token da Maple Finance, uma plataforma de crédito on-chain que concede empréstimos a instituições e oferece produtos como o syrupUSDC. Em 2024 ele substituiu o antigo token MPL da Maple, com conversão de 1 MPL para 100 SYRUP. Os detentores podem fazer staking de SYRUP e participar da governança do protocolo.","terra-luna":"Terra Luna Classic (LUNC) é a moeda nativa da blockchain Terra original, que entrou em colapso em maio de 2022 quando a stablecoin algorítmica UST perdeu a paridade com o dólar. Depois disso, uma nova rede assumiu o nome LUNA, e a antiga passou a se chamar Terra Classic, com a moeda LUNC. A rede, baseada no Cosmos SDK, hoje é mantida pela comunidade, e o LUNC é usado para taxas, staking e governança, incluindo votações sobre queima de tokens.","tether":"Tether (USDT) é uma stablecoin emitida pela empresa Tether desde 2014 e criada para valer um dólar americano. A empresa afirma que cada token é lastreado por reservas, principalmente títulos de curto prazo do Tesouro dos EUA e equivalentes de caixa. O USDT é muito usado para negociar, fazer pagamentos e movimentar dólares entre plataformas, e circula em redes como Ethereum, TRON e Solana.","tether-gold":"Tether Gold (XAUT) é um token emitido pela Tether em que cada unidade representa a propriedade de uma onça troy de ouro físico guardado em um cofre na Suíça. Ele permite manter e transferir ouro em uma blockchain, inclusive em pequenas frações de onça. O XAUT funciona como token no Ethereum, e os detentores podem consultar as barras específicas alocadas ao seu endereço.","tezos":"Tezos (XTZ) é uma blockchain de camada 1 cuja rede principal entrou no ar em 2018. Ela usa prova de participação líquida: os detentores podem produzir blocos (o chamado baking) ou delegar a um baker, e as atualizações do protocolo são propostas e votadas on-chain, sem hard forks. O XTZ é usado para pagar taxas de transações e de contratos inteligentes.","the-graph":"The Graph (GRT) é o token de um protocolo descentralizado de indexação que organiza dados de blockchain em APIs abertas chamadas subgraphs, consultadas por aplicativos em vez de servidores próprios. Indexadores fazem staking de GRT para prestar o serviço, delegadores destinam GRT a indexadores e curadores sinalizam subgraphs úteis. As consultas são pagas em GRT; a rede principal foi lançada em dezembro de 2020.","the-open-network":"Gram (GRAM), antes chamado Toncoin, é a moeda nativa da The Open Network (TON), uma blockchain de prova de participação cujo projeto começou no Telegram e hoje é desenvolvida por uma comunidade independente. A moeda paga taxas da rede, é usada no staking dos validadores e serve para pagamentos e miniapps dentro do ecossistema do Telegram. Também existem versões encapsuladas no Ethereum e na BNB Smart Chain.","the-sandbox":"SAND é o token do The Sandbox, um mundo virtual e plataforma de criação de jogos da Animoca Brands, onde os jogadores constroem, possuem e administram experiências em terrenos digitais. SAND é usado para comprar lotes LAND e itens do jogo, pagar taxas da plataforma e participar de staking e votações de governança. É um token ERC-20 no Ethereum, com versões na Polygon e na Base.","theta-token":"THETA é o token de governança e staking da Theta Network, blockchain lançada em 2019 para distribuição descentralizada de vídeo e, mais recentemente, computação de IA e GPU pelo serviço EdgeCloud. A Theta usa dois tokens: o THETA fica em staking com nós validadores e guardiões para proteger a rede, e o TFUEL paga transações e serviços. A oferta de THETA é fixa em 1 bilhão.","thorchain":"RUNE é o ativo nativo da THORChain, rede que permite trocar moedas nativas entre blockchains, como BTC por ETH, sem tokens embrulhados. Cada pool de liquidez combina um ativo com RUNE, e os operadores de nós precisam depositar RUNE como garantia para proteger os cofres que guardam os fundos dos usuários. A THORChain usa o Cosmos SDK e começou a operar trocas entre redes em 2021.","tradable-na-rent-financing-platform-sstn":"Este token representa uma posição de crédito privado tokenizada: exposição a uma linha de financiamento norte-americana que financia pagamentos de aluguel, emitida pela plataforma Tradable. Ele roda na zkSync, uma rede de camada 2 do Ethereum, e em geral é voltado a investidores institucionais e qualificados, não ao trading do dia a dia. O ticker PC0000031 é um código de produto, e a posse costuma ser restrita a participantes elegíveis.","tron":"TRON (TRX) é a moeda nativa da blockchain TRON, fundada por Justin Sun em 2017. O TRX é usado para obter recursos da rede, chamados de largura de banda e energia, e é colocado em staking para votar nos 27 Super Representantes que produzem blocos com prova de participação delegada. A TRON é uma das redes mais usadas para transferir a stablecoin USDT.","true-usd":"TrueUSD (TUSD) é uma stablecoin em dólar lançada em 2018, pensada para ser resgatável 1:1 por dólares mantidos em reserva. Foi criada originalmente pela equipe da TrustToken e hoje é emitida pela Techteryx, com relatórios de reservas divulgados por meio de atestações de terceiros. É usada em pagamentos, pares de negociação e DeFi na Ethereum, TRON, BNB Smart Chain e outras redes.","trust-wallet-token":"TWT é o token da Trust Wallet, aplicativo de carteira cripto de autocustódia que a Binance adquiriu em 2018. Lançado em 2020, ele dá acesso a benefícios no app, como descontos em taxas, e à participação em recursos da comunidade. Hoje fica principalmente na BNB Smart Chain, depois de ter sido emitido primeiro na antiga BNB Beacon Chain.","unibase":"UB é o token da Unibase, um projeto de IA que se apresenta como uma camada de memória descentralizada para agentes de IA, permitindo que eles guardem e compartilhem dados de longo prazo entre aplicativos. É emitido na BNB Smart Chain e no Ethereum e usado para acesso, incentivos e participação no ecossistema. Por ser um projeto novo, os detalhes do modelo do token ainda podem mudar.","uniswap":"UNI é o token de governança da Uniswap, uma exchange descentralizada onde as pessoas trocam tokens direto da carteira por meio de pools de liquidez automatizados, sem livro de ofertas. Quem tem UNI vota em mudanças no protocolo e no uso da tesouraria da comunidade. O token foi lançado em 2020 com um airdrop para usuários anteriores, e a Uniswap também criou sua própria rede de camada 2 no Ethereum, a Unichain.","united-stables":"United Stables (U) é uma stablecoin criada para manter o valor de um dólar americano. Como outras stablecoins em dólar, é usada para mover valor entre carteiras e plataformas, negociar e servir de unidade estável no DeFi. É emitida em várias redes, incluindo BNB Smart Chain, Ethereum e TRON.","usa":"USAT é uma stablecoin em dólar americano criada para manter paridade de um para um com o dólar, disponível no Ethereum e na Celo. Stablecoins como a USAT servem para movimentar valor em dólar on-chain, para pagamentos e liquidações e como ativo estável em trading e DeFi. O lastro em reservas e as condições de resgate são definidos pelo emissor, então vale ler as divulgações dele.","usd-coin":"USDC é uma stablecoin atrelada ao dólar americano, emitida pela Circle e lançada em 2018. Cada token foi feito para ser resgatado na proporção de um para um em dólares e é lastreado por dinheiro e títulos de curto prazo do Tesouro dos EUA, com relatórios periódicos das reservas. É usado em negociação, pagamentos e DeFi, e é emitido nativamente em várias blockchains, como Ethereum, Sui, Hedera e XRP Ledger.","usd1-wlfi":"USD1 é uma stablecoin atrelada ao dólar americano lançada em 2025 pela World Liberty Financial. Cada token foi pensado para ser resgatável na proporção de um para um em dólares e é lastreado por reservas em dinheiro, títulos do Tesouro americano de curto prazo e equivalentes de caixa, sob custódia da BitGo. É emitido em várias redes, como Ethereum, BNB Smart Chain, Solana e TRON.","usdai":"USDai é um token atrelado ao dólar emitido pelo protocolo USD.AI, que direciona capital on-chain para empréstimos garantidos por hardware de computação para IA, como GPUs. É possível manter USDai como unidade de conta estável ou depositá-lo no protocolo para receber uma versão em staking ligada a essa atividade de crédito. O token circula em Arbitrum, Ethereum, Base e Plasma.","usdd":"USDD é uma stablecoin atrelada ao dólar que surgiu na rede TRON em 2022. Ela busca manter o valor de um dólar e é lastreada por uma reserva de criptoativos com valor superior ao de USDD em circulação. É usada principalmente para pagamentos, pares de negociação e empréstimos no ecossistema DeFi da TRON, e também é emitida no Ethereum e na BNB Smart Chain.","usdgo":"USDGO é uma stablecoin criada para acompanhar o dólar americano na proporção de um para um. É usada como outras stablecoins em dólar: para manter um saldo estável, transferir valor entre carteiras e servir de unidade de conta em negociações e no DeFi. É emitida na Solana, no Ethereum e na Morph L2.","usds":"USDS é uma stablecoin atrelada ao dólar emitida pela Sky, protocolo antes conhecido como MakerDAO, e lançada em 2024 como versão atualizada do DAI; DAI e USDS podem ser convertidos um para um. Ela é gerada a partir de garantias depositadas no protocolo, incluindo criptoativos e ativos do mundo real, e circula no Ethereum, Base, Arbitrum e Solana.","usdtb":"USDtb é uma stablecoin em dólar emitida pela Ethena, a equipe por trás do USDe, lançada no fim de 2024. Ao contrário do USDe, ela é lastreada principalmente em cotas do BUIDL, o fundo tokenizado de títulos do Tesouro dos EUA da BlackRock, além de reservas de alta liquidez, e não em posições cripto com hedge. É usada como ativo estável de liquidação e como parte das reservas de outros produtos da Ethena.","useless-3":"Useless Coin (USELESS) é um token meme lançado na Solana em 2025 que se apresenta abertamente como algo sem utilidade. O apelo vem da própria piada e da comunidade online em torno dela, e não de um produto ou protocolo. Há também uma versão do token na BNB Smart Chain.","usual-usd":"USD0 é uma stablecoin em dólar emitida pelo protocolo Usual, projetada para ser lastreada 1:1 em ativos reais de curto prazo, como títulos do Tesouro dos EUA tokenizados. Os usuários podem depositar USD0 nos produtos de staking da Usual para receber o token USUAL, e o USD0 é usado como base em empréstimos e pools de liquidez DeFi. Ele funciona na Ethereum e em outras redes EVM.","usx":"USX é uma stablecoin emitida na Solana que busca manter o valor de um dólar americano por token. Como outros tokens atrelados ao dólar, é usada principalmente para pagamentos, para movimentar valor entre aplicativos e como unidade estável em protocolos DeFi. O mecanismo de paridade e os ativos de lastro são definidos pelo emissor, por isso vale conferir as informações de reservas ou colateral que ele publica.","vaulta":"Vaulta (A) é a moeda nativa da rede Vaulta, a blockchain antes chamada EOS, que mudou de marca em 2025 e trocou EOS por A na proporção de um para um. A rede usa prova de participação delegada e foca em serviços bancários e de pagamento Web3. A paga os recursos da rede e pode ser colocada em staking para ajudar a protegê-la.","vechain":"VET é o token nativo da VeChainThor, blockchain pública lançada em 2018 com foco em rastreamento de cadeias de suprimentos e uso corporativo. A VeChain usa um modelo de dois tokens: manter VET gera VTHO, que é o token efetivamente gasto nas taxas de transação. A rede tem funcionado com um consenso do tipo prova de autoridade, com validadores conhecidos e verificados.","venice-token":"Venice Token (VVV) é o token da Venice.ai, uma plataforma de IA focada em privacidade fundada por Erik Voorhees, que roda modelos de código aberto sem armazenar as conversas dos usuários. Fazer staking de VVV dá acesso a uma parte da capacidade da API da Venice sem pagar por requisição. O token foi lançado em janeiro de 2025 na Base, rede de camada 2 do Ethereum.","virtual-protocol":"Virtuals Protocol é uma plataforma para criar agentes de IA e ser coproprietário deles, principalmente na rede Base, onde cada agente pode ter seu próprio token. O VIRTUAL é o ativo base do ecossistema: novos tokens de agentes são pareados com VIRTUAL em pools de liquidez, e ele é usado para pagar serviços e lançamentos de agentes. O projeto se chamava PathDAO, uma guilda de games, e virou Virtuals em 2024.","whitebit":"WhiteBIT Coin (WBT) é o token utilitário da corretora de criptomoedas WhiteBIT, plataforma fundada na Ucrânia. Os detentores podem usar o WBT para obter vantagens no ecossistema WhiteBIT, como taxas de negociação reduzidas e acesso a recursos da plataforma. O token foi emitido primeiro no Ethereum e na TRON e também é usado na Whitechain, blockchain desenvolvida pela equipe da WhiteBIT.","world-liberty-financial":"WLFI é o token de governança da World Liberty Financial, um projeto de finanças descentralizadas lançado em 2024 e ligado à família do presidente dos EUA, Donald Trump. Os detentores podem votar em propostas sobre a plataforma e seus produtos, entre eles a stablecoin USD1. O token começou sem possibilidade de transferência e passou a ser negociado em 2025.","worldcoin-wld":"WLD é o token do World (antes Worldcoin), projeto cofundado por Sam Altman e desenvolvido pela Tools for Humanity. A proposta é oferecer às pessoas uma prova digital, com foco em privacidade, de que são humanos únicos, chamada World ID, verificada por um dispositivo de leitura de íris conhecido como Orb. O WLD é usado em governança e incentivos do ecossistema e funciona no Ethereum, na Optimism e na World Chain.","wormhole":"W é o token de governança da Wormhole, um protocolo de mensagens que permite que blockchains como Solana, Ethereum e muitas outras troquem dados e tokens entre si. As mensagens entre redes são verificadas por 19 validadores independentes chamados Guardians. O W foi lançado em 2024 com um grande airdrop para a comunidade e foi projetado como token multichain nativo, que circula entre redes sem precisar ser encapsulado.","xdce-crowd-sale":"XDC é a moeda nativa da XDC Network, uma blockchain compatível com EVM lançada pela XinFin e voltada para financiamento de comércio exterior e ativos do mundo real tokenizados. Ela usa um sistema de prova de participação delegada chamado XDPoS, em que masternodes produzem blocos de forma rápida e barata. O XDC paga as transações e é usado em staking pelos operadores de masternodes; o id desta página se refere ao XDCE, token da venda inicial do projeto.","ylds":"YLDS é um token em dólar que rende juros, emitido pela Figure na blockchain Provenance. Diferente da maioria das stablecoins, ele é registrado na SEC dos EUA como valor mobiliário e paga juros aos detentores, com reservas em ativos de curto prazo e alta qualidade. Foi pensado para pagamentos e liquidações em que se quer um token em dólar que também renda juros.","zama":"ZAMA é o token do Zama Protocol, desenvolvido pela Zama, empresa de criptografia conhecida pelo trabalho com criptografia totalmente homomórfica (FHE). A FHE permite processar dados sem descriptografá-los, e a Zama usa isso para trazer saldos confidenciais e contratos inteligentes privados a blockchains existentes. O token paga os serviços do protocolo e é colocado em staking pelos operadores que mantêm a rede.","zcash":"Zcash (ZEC) é uma criptomoeda focada em privacidade, lançada em 2016, que roda em sua própria blockchain de prova de trabalho. Ela usa provas de conhecimento zero (zk-SNARKs) para permitir transações blindadas, que ocultam remetente, destinatário e valor, enquanto as transações transparentes funcionam de modo parecido com o Bitcoin. O ZEC é usado em pagamentos e tem oferta máxima de 21 milhões de moedas.","zebec-network":"ZBCN é o token da Zebec Network, projeto de pagamentos que começou na Solana e ficou conhecido pelos pagamentos em streaming, em que o dinheiro chega ao destinatário segundo a segundo, por exemplo em folhas de pagamento. O projeto também trabalha com cartões cripto e outras pontes entre ativos digitais e pagamentos do dia a dia. ZBCN é usado para governança e staking e substituiu o antigo token ZBC."});
